};
in vec2 v_uv0;
uniform sampler2D texture;
  float rand(vec2 co) {
    return fract(sin(dot(co.xy , vec2(12.9898, 78.233))) * 43758.5453);
  }
  vec4 blur(vec2 uv){
        float _blurAmount = 0.04;
    vec3 blurred = vec3(0.0);
    for(float i = 0.0; i < 6.0; i ++ )
    {
      vec2 q = vec2(cos(degrees((i / 6.0) * 360.0)), sin(degrees((i / 6.0) * 360.0))) * (rand(vec2(i, uv.x + uv.y)) + _blurAmount);
      vec2 uv2 = uv + (q * _blurAmount+0.5);
      blurred += texture2D(texture, uv).rgb / 2.0;
      q = vec2(cos(degrees((i / 6.0) * 360.0)), sin(degrees((i / 6.0) * 360.0))) * (rand(vec2(i + 2.0, uv.x + uv.y + 24.0)) + _blurAmount);
      uv2 = uv + (q * _blurAmount);
      blurred += texture2D(texture, uv2).rgb / 2.0;
    }
    blurred /= 6.0;
    return vec4(blurred,texture2D(texture, uv).a);
  }
  void main()
  {
    gl_FragColor = vec4(blur(v_uv0));
  }

